def _apply_pagination(self, querystring: str, **kwargs) -> str:
    # LIMIT BY isn't really a pagination per se but since we need
    # to add this to the query right before an actual LIMIT clause
    # this is good enough.
    if self._limit_by:
        querystring += self._limit_by_sql(**kwargs)

    # Apply FINAL and SAMPLE clauses before pagination
    if self._final:
        querystring += self._final_sql()

    if self._sample is not None:
        querystring += self._sample_sql()

    return super()._apply_pagination(querystring, **kwargs)

def _final_sql(self) -> str:
    return " FINAL"

def _sample_sql(self) -> str:
    if self._sample_offset is not None:
        return f" SAMPLE {self._sample} OFFSET {self._sample_offset}"
    return f" SAMPLE {self._sample}"

